<?php declare(strict_types=1);namespace App\Services;use App\Core\Auth;use App\Core\Config;use App\Core\Cron;use App\Core\DB;use App\Core\I18n;use App\Models\Setting;final class AdminUi{public const SETTING='admin.ui_defaults';public const THEMES=['aurora'=>['modes'=>['light','dark'],'layout'=>'floating','bg'=>'aurora'],'classique'=>['modes'=>['light','dark'],'layout'=>'docked','bg'=>'solid'],'saphir'=>['modes'=>['light','dark'],'layout'=>'docked','bg'=>'solid'],'obsidian'=>['modes'=>['dark'],'layout'=>'docked','bg'=>'solid'],'nordic'=>['modes'=>['light','dark'],'layout'=>'docked','bg'=>'solid'],'ember'=>['modes'=>['dark'],'layout'=>'floating','bg'=>'soft'],'executif'=>['modes'=>['light'],'layout'=>'docked','bg'=>'solid']];public const ACCENTS=['indigo','blue','violet','emerald','rose','orange','cyan','slate'];public const BASE=['theme'=>'aurora','mode'=>'light','accent'=>null,'radius'=>'normal','density'=>'comfortable','bg'=>'theme'];public static function normalize(mixed $e):array{$f=self::BASE;if(!is_array($e)){return $f;}if(isset($e['theme'])&&is_string($e['theme'])&&isset(self::THEMES[$e['theme']])){$f['theme']=$e['theme'];}if(isset($e['mode'])&&in_array($e['mode'],['light','dark','auto'],true)){$f['mode']=$e['mode'];}if(isset($e['accent'])&&is_string($e['accent'])){if(in_array($e['accent'],self::ACCENTS,true)){$f['accent']=$e['accent'];}elseif(preg_match('/^#[0-9a-fA-F]{6}$/',$e['accent'])){$f['accent']=strtolower($e['accent']);}}if(isset($e['radius'])&&in_array($e['radius'],['compact','normal','round'],true)){$f['radius']=$e['radius'];}if(isset($e['density'])&&in_array($e['density'],['comfortable','compact'],true)){$f['density']=$e['density'];}if(isset($e['bg'])&&in_array($e['bg'],['theme','soft','solid','aurora'],true)){$f['bg']=$e['bg'];}return $f;}public static function defaults():?array{$U=Setting::get(self::SETTING);return is_array($U)&&$U?self::normalize($U):null;}public static function resolvedMode(array $i):string{$g=self::THEMES[$i['theme']]['modes']